`timescale 1ns/1ps
// Auto-generated by fpga_toolbox.protocol_tb_emitter (protocol=axi4_stream)
// AXI4-Stream sink-side testbench: drives TDATA/TVALID and obeys TREADY.
module tb_axs_fifo_axi4_stream;
  // DUT 可能有 TB 不关心的额外端口（调试/测试/scan），
  // 显式连接覆盖不到会触发 PINMISSING，故显式关闭。
  /* verilator lint_off PINMISSING */
  logic          aclk = 0, aresetn = 0;
  // errs 必须是 int：`logic errs` 只有 1 位，累加偶数次错误会溢出回 0，
  // 于是一个完全卡死的 DUT（5 次握手超时 + 1 次 beat 计数不符 = 6 次错误）
  // 反而打印 "PASS" 并 rc=0 —— 实测踩中，正是本模板要防的假通过。
  int            errs = 0;
  int            accepted = 0;
  int            driven = 0;
  logic [31:0] s_axis_tdata = '0;
  logic          s_axis_tvalid = 0;
  logic          s_axis_tready;
  logic          s_axis_tlast = 0;
  logic [3:0] s_axis_tkeep = '1;
  logic [3:0] s_axis_tid = 0;
  logic [3:0] s_axis_tdest = 0;

  axs_fifo dut (
    .aclk(aclk), .aresetn(aresetn),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .s_axis_tlast(s_axis_tlast),
    .s_axis_tkeep(s_axis_tkeep),
    .s_axis_tid(s_axis_tid),
    .s_axis_tdest(s_axis_tdest)
  );
  always #5 aclk = ~aclk;

  localparam int PKT_LEN = 4;
  // 驱动序列（TB 是数据源，参考模型即它自己驱动的内容）
  logic [31:0] exp_data [0:PKT_LEN-1] = '{32'h11223344, 32'h13344556, 32'h35465768, 32'h58697A8B};
  logic [3:0] exp_keep [0:PKT_LEN-1] = '{4'hF, 4'hF, 4'hF, 4'h1};

  // 单 beat 握手：驱动 payload → 等 TREADY → 撤销 TVALID。
  // payload 在 TVALID 期间必须保持稳定（AXI4-Stream 强制规则），所以只在
  // 握手成功后才返回，由调用方更新下一拍。
  task automatic axis_send_beat(
    input int idx,
    input logic [31:0] data_v,
    input logic [3:0] keep_v,
    input logic last_v
  );
    int waited = 0;
    s_axis_tdata = data_v;
    s_axis_tlast = last_v;
    s_axis_tkeep = keep_v;
    s_axis_tid = idx[3:0];
    s_axis_tdest = idx[3:0];
    s_axis_tvalid = 1;
    // 逐拍等 TREADY；超时说明 DUT 流控卡死
    @(posedge aclk); #1;
    while (!s_axis_tready) begin
      // payload 必须在等待期间保持不变（自检模板自身的合规性）
      if (s_axis_tdata !== data_v || s_axis_tkeep !== keep_v || s_axis_tlast !== last_v) begin
        $display("[CHECK] id=AXIS_STABLE | cat=payload_stability | beat=%0d | exp=data:0x%08h | got=data:0x%08h | status=FAIL",
                 idx, data_v, s_axis_tdata);
        errs++;
      end
      waited++;
      if (waited > 1000) begin
        $display("[CHECK] id=AXIS_TIMEOUT | cat=handshake | beat=%0d | exp=TREADY within 1000 cycles | got=never asserted | status=FAIL", idx);
        errs++;
        s_axis_tvalid = 0;
        disable axis_send_beat;
      end
      @(posedge aclk); #1;
    end
    // 采样点：TREADY 为高的这个上升沿完成了一次传输
    accepted++;
    s_axis_tvalid = 0;
    @(posedge aclk); #1;
  endtask

  initial begin
    // ---- waveform dump (optional; enable with +WAVE on the sim command line) ----
    if ($test$plusargs("WAVE")) begin
      if ($value$plusargs("WAVE_FILE=%s", wave_path)) begin
        $dumpfile(wave_path);
      end else begin
        $dumpfile("wave.vcd");
      end
      $dumpvars(0, tb_axs_fifo_axi4_stream);
    end
    repeat (3) @(posedge aclk);
    aresetn = 1;
    @(posedge aclk); #1;

    // 包 1：4 beat 连续突发（前 n-1 拍 TKEEP 全有效，末拍收窄）
    for (int i = 0; i < PKT_LEN; i++) begin
      axis_send_beat(i, exp_data[i], exp_keep[i], (i == PKT_LEN - 1));
      driven++;
    end
    // 包 2：单 beat 短包（TLAST 立即有效）—— 检查短包边界
    axis_send_beat(0, 32'hDEADBEEF, 4'h1, 1'b1);
    driven++;

    if (accepted !== driven) begin
      $display("[CHECK] id=AXIS_COUNT | cat=beat_accounting | exp=%0d beats accepted | got=%0d | status=FAIL", driven, accepted);
      errs++;
    end

    if (errs == 0) begin
      $display("PASS: axi4_stream %0d beats accepted, TREADY handshake / payload stability / TKEEP+TLAST boundaries verified", accepted);
      $finish;
    end else begin
      $display("FAIL: axi4_stream %0d errors", errs);
      $fatal(1);
    end
  end

  // 全局看门狗：DUT 若永久拉低 TREADY，逐拍超时会兜住；这里兜住其他挂死
  initial begin
    #2000000;
    $display("FAIL: axi4_stream timeout (simulation did not complete)");
    $fatal(1);
  end
  string wave_path;
endmodule
